// Generates the permission files for every command this plugin exposes
// (permissions/autogenerated/…). Apps grant them through a capability,
// normally with the "polar-license:default" set defined in
// permissions/default.toml.
const COMMANDS: &[&str] = &["status", "activate", "release", "launch_check"];

fn main() {
    tauri_plugin::Builder::new(COMMANDS).build();
}
